export const uid=()=>globalThis.crypto.randomUUID();
export const today=()=>{const d=new Date();return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`};
export const xpFor=m=>Math.round(20+Number(m.difficulty)*8+Number(m.fear)*4+Number(m.urgency)*3);
export const level=x=>Math.floor(Math.sqrt(x/100))+1;
export const progress=x=>{let l=level(x);return {level:l,current:x-(l-1)**2*100,total:(l*l-(l-1)**2)*100}};
export function seed(){return {version:1,profile:{name:'Adventurer',title:'Writing my next chapter',avatar:'',xp:0,coins:0,energy:80},settings:{accent:'#dfb979',compact:false,light:false,cover:'',energyAware:true},missions:[{id:uid(),title:'Make space for a clear mind',description:'A little less noise. A little more intention.',icon:'◈',category:'Mindfulness',difficulty:2,urgency:2,fear:1,duration:10,coins:15,skills:['mind'],repeat:'daily',due:today(),notes:'',subtasks:[{title:'Find a quiet spot',done:false},{title:'Ten minutes of meditation',done:false}],status:'active'},{id:uid(),title:'Move your body',description:'A walk, a stretch, or your next personal best.',icon:'↗',category:'Wellbeing',difficulty:3,urgency:2,fear:1,duration:30,coins:25,skills:['body'],repeat:'daily',due:today(),notes:'',subtasks:[],status:'active'},{id:uid(),title:'Get lost in a good book',description:'Read a chapter. Discover a different perspective.',icon:'▤',category:'Learning',difficulty:2,urgency:1,fear:1,duration:20,coins:15,skills:['learn'],repeat:'daily',due:today(),notes:'',subtasks:[],status:'active'},{id:uid(),title:'Build something that matters',description:'Give your personal project an uninterrupted hour.',icon:'⌘',category:'Craft',difficulty:4,urgency:3,fear:3,duration:60,coins:40,skills:['craft'],repeat:'none',due:'',notes:'',subtasks:[],status:'active'}],skills:[{id:'mind',title:'Mindfulness',icon:'◈',category:'Mind',xp:0,description:'Practice being present.',notes:''},{id:'body',title:'Vitality',icon:'↗',category:'Body',xp:0,description:'Build a stronger foundation.',notes:''},{id:'learn',title:'Knowledge',icon:'▤',category:'Mind',xp:0,description:'Stay curious.',notes:''},{id:'craft',title:'Craft',icon:'⌘',category:'Creation',xp:0,description:'Make ideas real.',notes:''}],rewards:[{id:uid(),title:'Coffee & a slow morning',description:'Your favorite drink, without the rush.',icon:'☕',category:'Little joys',cost:75,quantity:-1,increase:0,purchases:0,inventory:0},{id:uid(),title:'An evening to play',description:'One guilt-free hour with your favorite game.',icon:'♟',category:'Recharge',cost:120,quantity:-1,increase:10,purchases:0,inventory:0},{id:uid(),title:'Something on your wishlist',description:'A little something you have been saving for.',icon:'✧',category:'Milestones',cost:400,quantity:1,increase:0,purchases:0,inventory:0}],history:[]};}
export function complete(s,id){const m=s.missions.find(m=>m.id===id);if(!m||m.status!=='active')return null;if(s.missions.some(c=>c.parent===id&&c.status==='active')||m.subtasks.some(t=>!t.done))throw Error('Finish the subtasks and child missions first.');const xp=xpFor(m);s.profile.xp+=xp;s.profile.coins+=m.coins;s.history.unshift({id:uid(),type:'complete',title:m.title,xp,coins:m.coins,at:new Date().toISOString()});for(const sk of s.skills.filter(sk=>m.skills.includes(sk.id)))sk.xp+=xp;m.status='completed';if(m.repeat!=='none'){const d=new Date((m.due||today())+'T12:00:00');const now=new Date(today()+'T12:00:00');if(d<now)d.setTime(now.getTime());if(m.repeat==='daily')d.setDate(d.getDate()+1);if(m.repeat==='weekly')d.setDate(d.getDate()+7);if(m.repeat==='monthly')d.setMonth(d.getMonth()+1);s.missions.push({...structuredClone(m),id:uid(),parent:'',status:'active',due:`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`,subtasks:m.subtasks.map(t=>({...t,done:false}))});}return xp;}
export function purchase(s,id){const r=s.rewards.find(r=>r.id===id);if(!r||r.quantity===0)throw Error('This reward is out of stock.');if(s.profile.coins<r.cost)throw Error('Keep going — you need more coins for this reward.');s.profile.coins-=r.cost;r.inventory++;r.purchases++;if(r.quantity>0)r.quantity--;s.history.unshift({id:uid(),type:'purchase',title:r.title,coins:-r.cost,at:new Date().toISOString()});r.cost+=r.increase;}
export function validate(s){if(!s||s.version!==1||!s.profile||!s.settings||!Array.isArray(s.missions)||!Array.isArray(s.skills)||!Array.isArray(s.rewards)||!Array.isArray(s.history))throw Error('Choose a Daemon Deck v1 backup.');const number=(n,min=0)=>typeof n==='number'&&Number.isFinite(n)&&n>=min;const str=n=>typeof n==='string';const image=n=>str(n)&&n.length<4000000&&(!n||/^data:image\/(png|jpeg|webp|gif);base64,[A-Za-z0-9+/=]+$/.test(n));if(!str(s.profile.name)||!str(s.profile.title)||!image(s.profile.avatar)||!number(s.profile.xp)||!number(s.profile.coins)||!number(s.profile.energy)||s.profile.energy>100||!/^#[a-f\d]{6}$/i.test(s.settings.accent)||!image(s.settings.cover))throw Error('Invalid profile or appearance in backup.');for(const list of [s.missions,s.skills,s.rewards]){if(list.length>10000||new Set(list.map(x=>x.id)).size!==list.length)throw Error('Invalid backup record IDs.');for(const x of list)if(!str(x.id)||!str(x.title)||!str(x.icon)||!str(x.category)||!str(x.description)||x.image&&!image(x.image))throw Error('Invalid item in backup.');}for(const m of s.missions)if(!['active','completed','failed'].includes(m.status)||!['none','daily','weekly','monthly'].includes(m.repeat)||!Array.isArray(m.skills)||!m.skills.every(str)||!Array.isArray(m.subtasks)||!m.subtasks.every(t=>str(t.title)&&typeof t.done==='boolean')||!str(m.due)||!str(m.notes)||![m.difficulty,m.urgency,m.fear].every(n=>number(n)&&n<=5)||!number(m.coins)||!number(m.duration))throw Error('Invalid mission in backup.');for(const r of s.rewards)if(!number(r.cost)||!number(r.quantity,-1)||!number(r.increase)||!number(r.inventory)||!number(r.purchases))throw Error('Invalid reward in backup.');for(const sk of s.skills)if(!number(sk.xp)||!str(sk.notes))throw Error('Invalid skill in backup.');for(const h of s.history)if(!str(h.title)||!str(h.at)||!['complete','purchase','fail'].includes(h.type))throw Error('Invalid history in backup.');return s;}
